arguments.command:
cd /tmp/sv-8335dc2461ca470a97437389b6cd1f78/symbols && \
# The awk pattern seems to be matching incorrectly due to the ".." splitting. Let me fix it.
readelf --debug-dump=frames libmonosgen-2.0.so 2>/dev/null | grep "pc=" | \
sed 's/.*pc=\([0-9a-f]*\)\.\.\([0-9a-f]*\)/\1 \2/' | \
awk '{start=strtonum("0x"$1); end=strtonum("0x"$2)} 
  start <= 0x222098 && end > 0x222098 {printf "Frame#01: %s..%s (size 0x%x)\n", $1, $2, end-start}
  start <= 0x222234 && end > 0x222234 {printf "Frame#02: %s..%s (size 0x%x)\n", $1, $2, end-start}
  start <= 0x19bac0 && end > 0x19bac0 {printf "Frame#03: %s..%s (size 0x%x)\n", $1, $2, end-start}
  start <= 0x19bc14 && end > 0x19bc14 {printf "Frame#06: %s..%s (size 0x%x)\n", $1, $2, end-start}'

